1	import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
2	import { charIn, createRegExp, exactly, global, maybe, oneOrMore, whitespace, wordChar } from 'magic-regexp';
3	import * as path from 'pathe';
4	
5	/**
6	 * Reusable create-react-app compatibility capabilities for a Vite build.
7	 *
8	 * Every export here is application agnostic: the shapes handled are the ones
9	 * create-react-app itself defines (HTML template placeholders, `process.env`
10	 * inlining, the ambient `global` identifier, webpack tilde specifiers, and the
11	 * copied public directory). No capability branches on an application name,
12	 * revision, or source string.
13	 */
14	
15	export type CraEnvironment = Readonly<Record<string, string>>;
16	
17	const templatePlaceholder = createRegExp(
18		exactly('%').and(oneOrMore(wordChar).groupedAs('key')).and('%'),
19		[global],
20	);
21	
22	const tildePrefixedCssImport = createRegExp(
23		exactly('@import')
24			.and(oneOrMore(whitespace))
25			.and(maybe(exactly('url').and(maybe(whitespace)).and('(').and(maybe(whitespace))))
26			.and(charIn(`'"`))
27			.and('~'),
28		[global],
29	);
30	
31	const closingBodyTag = createRegExp(
32		exactly('<').and(maybe(whitespace)).and('/').and(maybe(whitespace)).and('body'),
33	);
34	
35	export function compareUtf16CodeUnits(left: string, right: string): number {
36		if (left === right) return 0;
37		return left < right ? -1 : 1;
38	}
39	
40	/**
41	 * Replace `%KEY%` template placeholders the way create-react-app's
42	 * InterpolateHtmlPlugin does: only keys present in the environment are
43	 * substituted, and unknown placeholders are preserved verbatim.
44	 */
45	export function substituteCraTemplatePlaceholders(
46		template: string,
47		environment: CraEnvironment,
48	): string {
49		return template.replace(templatePlaceholder, (match: string, key: string) =>
50			Object.hasOwn(environment, key) ? (environment[key] as string) : match,
51		);
52	}
53	
54	export type CraEntryDocumentOptions = Readonly<{
55		template: string;
56		entryModule: string;
57		environment?: CraEnvironment;
58	}>;
59	
60	/**
61	 * Turn a create-react-app `public/index.html` template into a Vite entry
62	 * document: placeholders are substituted and the application entry is injected
63	 * as a module script immediately before the closing body tag.
64	 */
65	export function craEntryDocument(options: CraEntryDocumentOptions): string {
66		const substituted = substituteCraTemplatePlaceholders(
67			options.template,
68			options.environment ?? {},
69		);
70		const script = `<script type="module" src="${options.entryModule}"></script>`;
71		const match = closingBodyTag.exec(substituted);
72		if (!match) return `${substituted}${substituted.endsWith('\n') ? '' : '\n'}${script}\n`;
73		return `${substituted.slice(0, match.index)}  ${script}\n  ${substituted.slice(match.index)}`;
74	}
75	
76	/**
77	 * Build the `define` map create-react-app's DefinePlugin provides: one entry per
78	 * environment key plus the whole `process.env` object for dynamic access.
79	 */
80	export function craProcessEnvironmentDefines(
81		environment: CraEnvironment,
82	): Readonly<Record<string, string>> {
83		const keys = Object.keys(environment).sort(compareUtf16CodeUnits);
84		const sorted = Object.fromEntries(keys.map((key) => [key, environment[key] as string]));
85		return Object.freeze({
86			...Object.fromEntries(
87				keys.map((key) => [`process.env.${key}`, JSON.stringify(environment[key])]),
88			),
89			'process.env': JSON.stringify(sorted),
90		});
91	}
92	
93	/**
94	 * The ambient identifier webpack 4 provides to every module it bundles for the
95	 * browser. webpack's runtime declares `global` itself (its `node.global`
96	 * option defaults to `true` on the webpack 4 line create-react-app 3 and 4
97	 * pin), so a dependency written against Node's `global` keeps working inside a
98	 * webpack browser bundle. Vite emits no such declaration: the same dependency
99	 * reaches the browser with a free `global` reference and throws
100	 * `ReferenceError: global is not defined` on first evaluation. Mapping the
101	 * identifier onto `globalThis` restores exactly the binding webpack supplied
102	 * and nothing else — it is a compile-time substitution of one free identifier,
103	 * so member accesses, property keys and locally bound `global` names are left
104	 * alone, and modules that never mention it emit byte-identical output.
105	 */
106	export function craGlobalIdentifierDefines(): Readonly<Record<string, string>> {
107		return Object.freeze({ global: 'globalThis' });
108	}
109	
110	export type CraDefineConfig = Readonly<{ define: Readonly<Record<string, string>> }>;
111	export type CraDefinePlugin = Readonly<{ name: string; config(): CraDefineConfig }>;
112	
113	/**
114	 * Contribute the webpack `global` binding as a Vite `define` entry. It is
115	 * contributed through the plugin's own configuration rather than asked of every
116	 * consumer, so any build that adopts the create-react-app adapter inherits the
117	 * ambient identifier its bundler used to provide.
118	 */
119	export function createCraGlobalIdentifierPlugin(): CraDefinePlugin {
120		return {
121			name: 'versionless-cra-global-identifier',
122			config() {
123				return { define: craGlobalIdentifierDefines() };
124			},
125		};
126	}
127	
128	/**
129	 * Rewrite webpack's tilde-prefixed bare specifiers in CSS `@import` rules to
130	 * plain bare specifiers, which Vite resolves through node resolution.
131	 */
132	export function rewriteWebpackTildeCssImports(code: string): string {
133		return code.replace(tildePrefixedCssImport, (match: string) => match.slice(0, -1));
134	}
135	
136	function pathWithoutQuery(id: string): string {
137		const index = id.indexOf('?');
138		return index === -1 ? id : id.slice(0, index);
139	}
140	
141	export type CraTransformResult = Readonly<{ code: string; map: null }>;
142	export type CraTransformPlugin = Readonly<{
143		name: string;
144		enforce: 'pre';
145		transform(code: string, id: string): CraTransformResult | null;
146	}>;
147	
148	export function createCraTildeCssImportPlugin(): CraTransformPlugin {
149		return {
150			name: 'versionless-cra-tilde-css-import',
151			enforce: 'pre',
152			transform(code, id) {
153				if (path.extname(pathWithoutQuery(id)) !== '.css') return null;
154				const rewritten = rewriteWebpackTildeCssImports(code);
155				return rewritten === code ? null : { code: rewritten, map: null };
156			},
157		};
158	}
159	
160	async function filesBelow(directory: string): Promise<string[]> {
161		const files: string[] = [];
162		for (const entry of await readdir(directory, { withFileTypes: true })) {
163			const item = path.join(directory, entry.name);
164			if (entry.isDirectory()) files.push(...(await filesBelow(item)));
165			else if (entry.isFile()) files.push(item);
166		}
167		return files;
168	}
169	
170	/**
171	 * The create-react-app public directory inventory: every file below the
172	 * directory except the excluded template, as sorted relative POSIX paths.
173	 */
174	export async function craPublicAssetPaths(
175		directory: string,
176		exclude: readonly string[] = [],
177	): Promise<readonly string[]> {
178		const excluded = new Set(exclude);
179		return (await filesBelow(directory))
180			.map((file) => path.relative(directory, file).split(path.sep).join('/'))
181			.filter((file) => !excluded.has(file))
182			.sort(compareUtf16CodeUnits);
183	}
184	
185	export type CraResolvedBuildConfig = Readonly<{ build: Readonly<{ outDir: string }> }>;
186	export type CraOutputPlugin = Readonly<{
187		name: string;
188		configResolved(config: CraResolvedBuildConfig): void;
189		closeBundle: Readonly<{ order: 'post'; sequential: true; handler(): Promise<void> }>;
190	}>;
191	
192	export type CraPublicDirectoryOptions = Readonly<{
193		directory: string;
194		exclude?: readonly string[];
195	}>;
196	
197	/**
198	 * Copy the create-react-app public directory into the build output the way
199	 * `react-scripts build` does, excluding the HTML template that becomes the
200	 * bundled entry document.
201	 */
202	export function createCraPublicDirectoryPlugin(
203		options: CraPublicDirectoryOptions,
204	): CraOutputPlugin {
205		let outputDirectory = '';
206		return {
207			name: 'versionless-cra-public-directory',
208			configResolved(config) {
209				outputDirectory = path.resolve(config.build.outDir);
210			},
211			closeBundle: {
212				order: 'post',
213				sequential: true,
214				async handler() {
215					if (!outputDirectory) throw new Error('CRA public directory outDir is unresolved');
216					for (const file of await craPublicAssetPaths(
217						options.directory,
218						options.exclude ?? [],
219					)) {
220						const destination = path.join(outputDirectory, file);
221						await mkdir(path.dirname(destination), { recursive: true });
222						await writeFile(destination, await readFile(path.join(options.directory, file)));
223					}
224				},
225			},
226		};
227	}
228	
229	export type CraViteAdapterOptions = Readonly<{
230		publicDirectory: string;
231		templateFile?: string;
232	}>;
233	
234	export type CraViteAdapterPlugins = readonly [
235		CraTransformPlugin,
236		CraDefinePlugin,
237		CraOutputPlugin,
238	];
239	
240	/**
241	 * The create-react-app compatibility plugin set: tilde CSS specifier rewriting,
242	 * the ambient `global` identifier, plus public directory replication.
243	 */
244	export function createCraViteAdapter(options: CraViteAdapterOptions): CraViteAdapterPlugins {
245		return [
246			createCraTildeCssImportPlugin(),
247			createCraGlobalIdentifierPlugin(),
248			createCraPublicDirectoryPlugin({
249				directory: options.publicDirectory,
250				exclude: [options.templateFile ?? 'index.html'],
251			}),
252		];
253	}
