1	import { createHash } from 'node:crypto';
2	import { readFile, readdir } from 'node:fs/promises';
3	import * as path from 'pathe';
4	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
5	
6	/**
7	 * Fixture-scoped verification for the HospitalRun create-react-app to Vite 8
8	 * build-stage lane. All application knowledge lives here; the reusable
9	 * capabilities it exercises live in @versionless/react and stay generic.
10	 */
11	
12	const root = path.resolve(import.meta.dirname, '../../../..');
13	const evidenceRoot = path.join(root, 'evidence/runs/react-hospitalrun');
14	const reactAdapterRoot = path.join(root, 'packages/frameworks/react/src');
15	
16	const sha256 = (value: string): string => createHash('sha256').update(value).digest('hex');
17	
18	export type HospitalRunBuildLane = Readonly<{
19		digest: string;
20		files: ReadonlyArray<Readonly<{ path: string; sha256: string }>>;
21	}>;
22	export type HospitalRunBuild = Readonly<{
23		bundler: string;
24		runtime: string;
25		equal: boolean;
26		first: HospitalRunBuildLane;
27		second: HospitalRunBuildLane;
28		serviceWorkerOutputs: readonly string[];
29	}>;
30	export type HospitalRunCompatibilityPin = Readonly<{
31		name: string;
32		version: string;
33		published: string;
34		reason: string;
35		tarball: string;
36		tarballSha256: string;
37	}>;
38	export type HospitalRunBuildProfile = Readonly<{
39		schemaVersion: string;
40		result: string;
41		fixture: string;
42		dependencyAcquisition: Readonly<{
43			consentId: string;
44			mode: string;
45			registryHosts: readonly string[];
46			lockfile: null;
47			compatibilityResolution: Readonly<{
48				label: string;
49				cutoff: string;
50				packagesPinned: number;
51				pins: readonly HospitalRunCompatibilityPin[];
52			}>;
53		}>;
54		builds: Readonly<{ baseline: HospitalRunBuild; target: HospitalRunBuild }>;
55		parity: Readonly<{
56			behavioral: string;
57			journeys: string;
58			runtimeEquivalence: string;
59			inventory: Readonly<{
60				baselineOnlyPaths: readonly string[];
61				targetOnlyPaths: readonly string[];
62				sharedPaths: readonly string[];
63				byteIdenticalSharedPaths: readonly string[];
64			}>;
65		}>;
66		gates: Readonly<Record<string, string>>;
67		integrity: Readonly<{ algorithm: string; canonicalDigest: string }>;
68	}>;
69	
70	export type HospitalRunBuildProfileVerification = Readonly<{
71		result: 'pass';
72		fixture: string;
73		baselineDeterministic: boolean;
74		targetDeterministic: boolean;
75		baselineFiles: number;
76		targetFiles: number;
77		compatibilityPins: number;
78		canonicalDigest: string;
79		applicationNamedProductSymbols: readonly string[];
80	}>;
81	
82	/**
83	 * The application identity must never leak into the reusable React product
84	 * surface. Anything that names this application there is a scope violation,
85	 * so the fixture asserts its own absence.
86	 */
87	export async function applicationNamedProductSymbols(
88		needle: string,
89	): Promise<readonly string[]> {
90		const lowered = needle.toLowerCase();
91		const offenders: string[] = [];
92		for (const entry of await readdir(reactAdapterRoot, { withFileTypes: true })) {
93			if (!entry.isFile()) continue;
94			const source = await readFile(path.join(reactAdapterRoot, entry.name), 'utf8');
95			if (source.toLowerCase().includes(lowered)) offenders.push(entry.name);
96		}
97		return offenders.sort();
98	}
99	
100	export async function readHospitalRunBuildProfile(): Promise<HospitalRunBuildProfile> {
101		const body = await readFile(path.join(evidenceRoot, 'build-profile.json'), 'utf8');
102		const profile = JSON.parse(body) as HospitalRunBuildProfile;
103		const { integrity, ...unsigned } = profile;
104		if (sha256(canonicalize(unsigned)) !== integrity.canonicalDigest)
105			throw new Error('HospitalRun build profile canonical digest differs');
106		return profile;
107	}
108	
109	/**
110	 * Every compatibility pin must be an era pin: published on or before the
111	 * declared cutoff, and carrying the reason it was needed.
112	 */
113	export function eraPinViolations(
114		pins: readonly HospitalRunCompatibilityPin[],
115		cutoff: string,
116	): readonly string[] {
117		const limit = Date.parse(cutoff);
118		return pins
119			.filter(
120				(pin) =>
121					!(Date.parse(pin.published) <= limit) ||
122					pin.reason.length === 0 ||
123					pin.version.length === 0,
124			)
125			.map((pin) => `${pin.name}@${pin.version}`);
126	}
127	
128	export async function verifyHospitalRunBuildProfile(): Promise<HospitalRunBuildProfileVerification> {
129		const profile = await readHospitalRunBuildProfile();
130		const { baseline, target } = profile.builds;
131		if (!baseline.equal || baseline.first.digest !== baseline.second.digest)
132			throw new Error('HospitalRun baseline builds are not deterministic');
133		if (!target.equal || target.first.digest !== target.second.digest)
134			throw new Error('HospitalRun target builds are not deterministic');
135		if (profile.parity.behavioral !== 'not-tested' || profile.parity.journeys !== 'not-tested')
136			throw new Error('HospitalRun build profile claims untested behavioral parity');
137		for (const gate of ['realServer', 'directWitnessJourneys', 'browserLocality'])
138			if (profile.gates[gate] !== 'not-run')
139				throw new Error(`HospitalRun browser gate ${gate} must remain not-run at build stage`);
140		if (profile.gates.baselineAuthenticity !== 'compatibility-labeled-not-authentic')
141			throw new Error('HospitalRun baseline must stay labeled as a compatibility resolution');
142		const { compatibilityResolution } = profile.dependencyAcquisition;
143		const violations = eraPinViolations(
144			compatibilityResolution.pins,
145			compatibilityResolution.cutoff,
146		);
147		if (violations.length > 0)
148			throw new Error(`HospitalRun compatibility pins are not era pins: ${violations.join(', ')}`);
149		if (compatibilityResolution.pins.length !== compatibilityResolution.packagesPinned)
150			throw new Error('HospitalRun compatibility pin count differs from the recorded pins');
151		const offenders = await applicationNamedProductSymbols('hospitalrun');
152		if (offenders.length > 0)
153			throw new Error(`Reusable React surface names the application: ${offenders.join(', ')}`);
154		return {
155			result: 'pass',
156			fixture: profile.fixture,
157			baselineDeterministic: baseline.equal,
158			targetDeterministic: target.equal,
159			baselineFiles: baseline.first.files.length,
160			targetFiles: target.first.files.length,
161			compatibilityPins: compatibilityResolution.pins.length,
162			canonicalDigest: profile.integrity.canonicalDigest,
163			applicationNamedProductSymbols: offenders,
164		};
165	}
